command:
// ==========================================
// LUNAS WIRKUNG: KALTE WUT (RONDRA)
//
// - nur auf den Wirkenden
// - Dauer: QS × 5 Kampfrunden
// - Nahkampf-Attacke +4
// - Parade nicht möglich
// - Fernkampf nicht möglich
// - Status: Raserei
// - Effektanlage über Block 6
// - Wirkungsende über Block 7
// - danach Betäubung bis zur nächsten Rast
//   oder bis jemand etwas dagegen unternimmt
// - öffentliche Gabenkarte über Block 11
// ==========================================

(async function () {

// +++ 1 - FRAMEWORK +++++++++++++++++++++++++++++++++++++++++++

const frameworkUuid = "Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn";
const frameworkFehlt = !globalThis.DSK?.Effekt?.Anwenden ||
    !globalThis.DSK?.EffektEnde?.Register || !globalThis.DSK?.QS?.Ermitteln ||
    !globalThis.DSK?.Token?.Finde || !globalThis.DSK?.GabenUI?.AnfrageKarteErstellen;

if (frameworkFehlt) {
    const fwMacro = await fromUuid(frameworkUuid);
    if (!fwMacro?.execute) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht gefunden!");
    await fwMacro.execute();
    await new Promise(resolve => setTimeout(resolve, 150));
}

const DSK_FW = globalThis.DSK;
if (!DSK_FW?.Effekt?.Anwenden || !DSK_FW?.EffektEnde?.Register ||
    !DSK_FW?.QS?.Ermitteln || !DSK_FW?.Token?.Finde ||
    !DSK_FW?.GabenUI?.AnfrageKarteErstellen
) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework 01.02 wurde nicht vollständig geladen!");

// +++ 2 - GRUNDDATEN ++++++++++++++++++++++++++++++++++++++++++

const gabenName = "Kalte Wut", vollerName = "Kalte Wut (Rondra)", ahne = "Rondra";
const endeKey = "kalteWutRondra";
const endeText = "Die Kalte Wut lässt nach und der Kampfrausch endet. Zurück bleibt jedoch eine Betäubung, die bis zur nächsten Rast anhält oder bis jemand etwas dagegen unternimmt.";

const changes = [
    { key: "system.meleeStats.attack", mode: 2, value: "4" },
    { key: "system.meleeStats.parry", mode: 2, value: "-100" },
    { key: "system.rangeStats.attack", mode: 2, value: "-100" }
];

DSK_FW.EffektEnde.Register(endeKey, vollerName, endeText);

// +++ 3 - WIRKENDER +++++++++++++++++++++++++++++++++++++++++++

let casterActor = canvas.tokens.controlled[0]?.actor || game.user.character || null;

if (!casterActor) {
    casterActor =
        canvas.tokens.placeables.map(token => token.actor)
            .find(actor => actor?.getFlag("world", "letzteGabenQS") !== undefined) ||
        game.actors.find(actor => actor.getFlag("world", "letzteGabenQS") !== undefined) || null;
}

if (!casterActor) return ui.notifications.warn("Luna sagt 🌙: Bitte wähle zuerst deinen Token aus!");
if (!game.user.isGM && !casterActor.isOwner) return ui.notifications.warn("Luna sagt 🌙: Du besitzt keine ausreichenden Rechte für diesen Akteur!");

const casterToken = DSK_FW.Token.Finde(casterActor);
if (!casterToken) return ui.notifications.warn("Luna sagt 🌙: Der Wirkende braucht einen Token auf der aktuellen Szene!");

const casterName = DSK_FW.ResolveTokenName(casterActor);

// +++ 4 - QS ERMITTELN ++++++++++++++++++++++++++++++++++++++++

const rollData = typeof testData !== "undefined" && testData
    ? testData
    : typeof args !== "undefined" && args[0] ? args[0] : null;

const qs = DSK_FW.QS.Ermitteln({
    actor: casterActor, gabenName,
    suchbegriffe: ["Kalte Wut Probe", "Kalte Wut"],
    testDataObj: rollData, fallback: 0, protokollieren: true
});

if (qs <= 0) {
    await DSK_FW.GabenUI.AnfrageKarteErstellen({
        gabenName: vollerName, ahne,
        beschreibung: "Die Kalte Wut konnte nicht entfesselt werden.",
        wirkender: casterName, ziele: [], misserfolge: [{ name: casterName }],
        dauerText: "0 Kampfrunden", gmBereich: false,
        angewendet: true, erfolgreich: false, anfragenderUserId: game.user.id
    });

    if (casterActor.getFlag("world", "letzteGabenQS") !== undefined) await casterActor.unsetFlag("world", "letzteGabenQS");
    if (casterActor.getFlag("world", "letzteGabenMessageId") !== undefined) await casterActor.unsetFlag("world", "letzteGabenMessageId");
    return;
}

// +++ 5 - ALTEN EFFEKT ENTFERNEN ++++++++++++++++++++++++++++++

const alteEffekte = casterActor.effects.filter(effect =>
    (effect.name || effect.label || "") === vollerName &&
    (!effect.getFlag("dsk", "casterUuid") ||
        effect.getFlag("dsk", "casterUuid") === casterActor.uuid)
);

if (alteEffekte.length) {
    await casterActor.deleteEmbeddedDocuments("ActiveEffect", alteEffekte.map(effect => effect.id));
}

// +++ 6 - EFFEKT ÜBER BLOCK 6 ++++++++++++++++++++++++++++++++

const dauerKR = qs * 5;
const beschreibung =
    `Das Rondrakind befindet sich in einem Kampfrausch und profitiert vom Status <b>Raserei</b>.` +
    `<br><br><b>Nahkampf:</b> Attacke +4, Parade nicht mehr möglich` +
    `<br><b>Fernkampf:</b> nicht mehr möglich` +
    `<br><br><b>Nachwirkung:</b> Nach dem Ende der Kalten Wut bleibt eine Betäubung bis zur nächsten Rast oder bis jemand etwas dagegen unternimmt.`;

const effekt = await DSK_FW.Effekt.Anwenden({
    name: vollerName, ahne, beschreibung,
    gabeZiel: "erwachte", qs, ziel: casterActor,
    changes, statuses: ["bloodrush"],
    duration: {
        rounds: dauerKR,
        seconds: dauerKR * 5,
        startTime: game.time.worldTime
    },
    showIcon: 1,
    flags: { dsk: {
        isKalteWut: true, casterUuid: casterActor.uuid, qs,
        wirkungsende: {
            sfName: endeKey, basisEffektName: vollerName,
            beschreibungFuerEnde: endeText
        }
    }}
});

// +++ 7 - EFFEKT PRÜFEN +++++++++++++++++++++++++++++++++++++++

const endeDaten = effekt?.getFlag("dsk", "wirkungsende");
const changesKorrekt = changes.every(erwartet =>
    (effekt?.changes || []).some(change =>
        change.key === erwartet.key &&
        Number(change.mode) === erwartet.mode &&
        Number(change.value) === Number(erwartet.value)
    )
);

const erfolgreich = Boolean(
    effekt &&
    (effekt.name || effekt.label || "") === vollerName &&
    effekt.getFlag("dsk", "isKalteWut") === true &&
    effekt.getFlag("dsk", "casterUuid") === casterActor.uuid &&
    Number(effekt.getFlag("dsk", "qs")) === qs &&
    effekt.statuses?.has("bloodrush") &&
    endeDaten?.sfName === endeKey &&
    endeDaten?.basisEffektName === vollerName &&
    endeDaten?.beschreibungFuerEnde === endeText &&
    changesKorrekt
);

// +++ 8 - ÖFFENTLICHE GABENKARTE ++++++++++++++++++++++++++++++

await DSK_FW.GabenUI.AnfrageKarteErstellen({
    gabenName: vollerName, ahne, beschreibung,
    wirkender: casterName,
    ziele: erfolgreich ? [{ name: casterName, rolle: "Betroffener" }] : [],
    misserfolge: erfolgreich ? [] : [{ name: casterName }],
    dauerText: `${dauerKR} Kampfrunden`,
    gmBereich: false, angewendet: true, erfolgreich,
    anfragenderUserId: game.user.id
});

// +++ 9 - QS-FLAGS AUFRÄUMEN ++++++++++++++++++++++++++++++++++

if (casterActor.getFlag("world", "letzteGabenQS") !== undefined) await casterActor.unsetFlag("world", "letzteGabenQS");
if (casterActor.getFlag("world", "letzteGabenMessageId") !== undefined) await casterActor.unsetFlag("world", "letzteGabenMessageId");

if (erfolgreich) ui.notifications.info(`Luna sagt 🌙: ${casterName} ist für ${dauerKR} Kampfrunden in Raserei!`);
else ui.notifications.error("Luna sagt 🌙: Kalte Wut konnte nicht vollständig angewendet werden!");

}).call(this);
